CREATE TABLE IF NOT EXISTS "approval_requests" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "approval_requests_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"token" uuid DEFAULT gen_random_uuid() NOT NULL,
	"recommendation_id" integer,
	"user_id" integer NOT NULL,
	"status" text DEFAULT 'pending' NOT NULL,
	"options" jsonb NOT NULL,
	"note" text,
	"last_error" text,
	"decided_by" integer,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"decided_at" timestamp with time zone,
	CONSTRAINT "approval_requests_token_unique" UNIQUE("token"),
	CONSTRAINT "approval_requests_status_valid" CHECK ("approval_requests"."status" IN ('pending', 'approved', 'declined'))
);
